  for (let i = 0; i < rects.length; i++) {
    const r = rects[i];
    const p = panels[i];
    if (!p) continue;
    if (r.slant) {
      ctx.save();
      ctx.beginPath();
      ctx.moveTo(r.x + r.slant, r.y);
      ctx.lineTo(r.x + r.w, r.y);
      ctx.lineTo(r.x + r.w - r.slant, r.y + r.h);
      ctx.lineTo(r.x, r.y + r.h);
      ctx.closePath();
